func init() {
	for id, a := range asieAirports {
		Airports[id] = a
	}
	for id, g := range asieGares {
		Gares[id] = g
		RegionCoach[id] = asieCompanies[asieRegion[id]]
	}
	for _, r := range []string{"est", "japon", "sud", "sudest", "centre"} {
		CoachCompanies = append(CoachCompanies, asieCompanies[r])
	}
	addActs(AsieActs)
	villeActs[AsieKey] = AsieActs
}

